SELECT o.type, o.path FROM obj o WHERE o.type='Function' AND (o.path LIKE '%:SetShell%' OR o.path LIKE '%:SwapShell%' OR o.path LIKE '%:ChangeShell%' OR o.path LIKE '%:ShellSwap%' OR o.path LIKE '%:SetDarkform%' OR o.path LIKE '%:SetDarkForm%' OR o.path LIKE '%:SetSkeletalMesh%' OR o.path LIKE '%:ChangeCharacterMesh%' OR o.path LIKE '%:SetCharacterMesh%' OR o.path LIKE '%:SetMesh%' OR o.path LIKE '%:EquipShell%' OR o.path LIKE '%:ApplySkin%' OR o.path LIKE '%:SetSkin%' OR o.path LIKE '%:ChangeSkin%') ORDER BY o.path
